node --input-type=module -e "
import { recordsMissingApplyStage } from './.claudinite/local/packs/claudinite/workRules/migration-apply-stage.mjs';
import { execSync } from 'node:child_process';
const cases = [
  ['packs/claudinite-tasks/migrations/2026-09-05-task-cadence-terms/migration.mjs', '2bbce2360a0d42b6c2d52da9d5b92060d0d00fb0'],
  ['engine/migrations/2026-07-19-local-pack-namespace/migration.mjs', null],
];
for (const [file, sha] of cases) {
  const head = execSync(sha ? \`git show \${sha}:\${file}\` : \`cat \${file}\`, { encoding: 'utf8' });
  const out = recordsMissingApplyStage([file], () => head, () => null);
  console.log(file.split('/migrations/')[1], '->', out.length ? out[0].key + ' | ' + out[0].fix.slice(0, 60) + '...' : 'NO FINDING');
}
"

